<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\BelongsToMany;
class Advertiser extends Model { use HasFactory, SoftDeletes; protected $fillable=['uuid','name','slug','status','website_url','billing_email','contact_name','contact_email','contact_phone','billing_address','notes']; public function campaigns(): HasMany{return $this->hasMany(AdvertisingCampaign::class);} public function invoices(): HasMany{return $this->hasMany(AdvertisingInvoice::class);} public function sponsorshipProposals(): HasMany{return $this->hasMany(SponsorshipProposal::class);} public function memberships(): HasMany{return $this->hasMany(AdvertiserMembership::class);} public function users(): BelongsToMany{return $this->belongsToMany(User::class,'advertiser_memberships')->withPivot(['role','is_primary','is_active','invited_at','accepted_at'])->withTimestamps();} }
